import random
random.seed(42)
draws = [random.randint(0, 99999) for _ in range(200)]
counts = {d: 0 for d in range(10)}
for n in draws:
    for ch in "%05d" % n:
        counts[int(ch)] += 1
print("SIMULATED draws:", len(draws), "(fixed seed 42, not real history)")
for d in range(10):
    print("digit", d, "appears", counts[d], "times across all positions")
print("total digit slots:", len(draws) * 5)
